window.QUESTIONS=[{"id":1,"question":{"ro":"Caracteristicile statului Republica Moldova consacrate în Constituție sunt:","ru":"Характеристики государства Республика Молдова, закреплённые в Конституции, следующие:"},"options":[{"key":"A","ro":"stat suveran, independent, social și inovațional;","ru":"суверенное, независимое, социальное и инновационное государство;"},{"key":"B","ro":"stat suveran, independent, unitar, indivizibil, de drept, democratic;","ru":"суверенное, независимое, унитарное, неразделимое, правовое, демократическое государство;"},{"key":"C","ro":"stat suveran, independent, unitar descentralizat;","ru":"суверенное, независимое, унитарное децентрализованное государство;"},{"key":"D","ro":"stat suveran, independent, social și laic.","ru":"суверенное, независимое, социальное и светское государство."}],"correct":"B"},{"id":2,"question":{"ro":"Sub aspect administrativ, teritoriul Republicii Moldova este organizat în:","ru":"С административной точки зрения территория Республики Молдова организована в:"},"options":[{"key":"A","ro":"regiuni, raioane, orașe, sate, noduri de cale ferată, unitatea teritorială autonomă Găgăuzia;","ru":"регионы, районы, города, сёла, железнодорожные узлы, автономная территориальная единица Гагаузия;"},{"key":"B","ro":"regiuni, raioane, orașe și sate;","ru":"регионы, районы, города и сёла;"},{"key":"C","ro":"sate, orașe, raioane, unitatea teritorială autonomă Găgăuzia.","ru":"сёла, города, районы, автономная территориальная единица Гагаузия"}],"correct":"C"},{"id":3,"question":{"ro":"Care din următoarele îndatoriri nu este consacrată în Constituția Republicii Moldova:","ru":"Какая из следующих обязанностей не закреплена в Конституции Республики Молдова:"},"options":[{"key":"A","ro":"devotament față de țară;","ru":"преданность стране;"},{"key":"B","ro":"conservarea și ocrotirea monumentelor istorice și culturale;","ru":"сохранение и охрана исторических и культурных памятников;"},{"key":"C","ro":"îndatorirea de a munci.","ru":"обязанность работать"}],"correct":"C"},{"id":4,"question":{"ro":"Poporul Republicii Moldova exercită suveranitatea:","ru":"Народ Республики Молдова осуществляет суверенитет:"},"options":[{"key":"A","ro":"prin organele sale reprezentative, prin referendum și prin adunările cetățenilor;","ru":"через свои представительные органы, через референдум и собрания граждан;"},{"key":"B","ro":"prin organele sale reprezentative, prin referendum și prin Adunarea Națională;","ru":"через свои представительные органы, через референдум и через Национальное Собрание;"},{"key":"C","ro":"în mod direct și prin organele sale reprezentative, în formele stabilite de Constituție;","ru":"непосредственно и через свои представительные органы в формах, установленных Конституцией;"},{"key":"D","ro":"în mod direct și prin organele sale reprezentative, în modul stabilit de Codul electoral","ru":"непосредственно и через свои представительные органы в порядке, установленном Избирательным кодексом"}],"correct":"C"},{"id":5,"question":{"ro":"În Republica Moldova percheziționarea, reținerea sau arestarea unei persoane sunt permise:","ru":"В Республике Молдова обыск, задержание или арест лица допускаются:"},"options":[{"key":"A","ro":"numai în cazul săvârșirii unei infracțiuni;","ru":"только в случае совершения преступления;"},{"key":"B","ro":"numai în cazurile și cu procedura prevăzute de lege;","ru":"только в случаях и с процедурой, предусмотренными законом;"},{"key":"C","ro":"numai în cazul săvârșirii unei contravenții, în baza mandatului emis de instanța de judecată;","ru":"только в случае совершения правонарушения, на основании ордера, выданного судом;"},{"key":"D","ro":"numai în cazul în care este nevoie de identificare, cu procedura prevăzută de lege.","ru":"только в случае необходимости идентификации, с процедурой, предусмотренной законом."}],"correct":"B"},{"id":6,"question":{"ro":"Membrii Guvernului Republicii Moldova depun jurământul în fața:","ru":"Члены Правительства Республики Молдова приносят присягу перед:"},"options":[{"key":"A","ro":"Parlamentului;","ru":"Парламентом;"},{"key":"B","ro":"Curții Constituționale;","ru":"Конституционным судом;"},{"key":"C","ro":"Președintelui Republicii Moldova;","ru":"Президентом Республики Молдова;"},{"key":"D","ro":"Parlamentului și a Curții Constituționale.","ru":"Парламентом и Конституционным судом."}],"correct":"C"},{"id":7,"question":{"ro":"Conform Constituției Republicii Moldova, cetățenii au dreptul să se adreseze autorităților publice prin petiții:","ru":"Согласно Конституции Республики Молдова, граждане имеют право обращаться к органам государственной власти с петициями:"},"options":[{"key":"A","ro":"doar în cazul în care sunt formulate în numele semnatarilor;","ru":"только в том случае, если они сформулированы от имени подписавших;"},{"key":"B","ro":"doar în cazul în care sunt întocmite în limba română;","ru":"только в том случае, если они составлены на румынском языке;"},{"key":"C","ro":"doar în cazul în care sunt încălcate anumite drepturi.","ru":"только в том случае, если нарушены определённые права"}],"correct":"A"},{"id":8,"question":{"ro":"Avocatul Poporului din Republica Moldova poate fi revocat din funcție:","ru":"Уполномоченный по правам человека (Avocatul Poporului) в Республике Молдова может быть освобождён от должности:"},"options":[{"key":"A","ro":"la cererea Președintelui Republicii Moldova;","ru":"по просьбе Президента Республики Молдова;"},{"key":"B","ro":"prin hotărârea Parlamentului, adoptată cu votul a 2/3 din deputații aleși;","ru":"постановлением Парламента, принятым 2/3 голосов избранных депутатов;"},{"key":"C","ro":"la cererea Consiliului Superior al Magistraturii, cu votul a 2/3 din membri.","ru":"по просьбе Высшего совета магистратуры, 2/3 голосов членов"}],"correct":"B"},{"id":9,"question":{"ro":"Alegerile deputaților în Parlamentul Republicii Moldova se desfășoară:","ru":"Выборы депутатов в Парламент Республики Молдова проводятся:"},"options":[{"key":"A","ro":"în cel mult 2 luni de la expirarea mandatului sau de la dizolvarea Parlamentului precedent;","ru":"не позднее 2 месяцев с истечения срока полномочий или с роспуска предыдущего Парламента;"},{"key":"B","ro":"în cel mult 90 de zile de la dizolvarea Parlamentului precedent;","ru":"не позднее 90 дней с роспуска предыдущего Парламента;"},{"key":"C","ro":"în cel mult 60 de zile de la expirarea mandatului;","ru":"не позднее 60 дней с истечения срока полномочий;"},{"key":"D","ro":"în cel mult 3 luni de la expirarea mandatului sau de la dizolvarea Parlamentului precedent","ru":"не позднее 3 месяцев с истечения срока полномочий или с роспуска предыдущего Парламента"}],"correct":"D"},{"id":10,"question":{"ro":"Președintele Parlamentului Republicii Moldova poate fi revocat:","ru":"Председатель Парламента Республики Молдова может быть отстранён:"},"options":[{"key":"A","ro":"cu majoritatea voturilor deputaților aleși;","ru":"большинством голосов избранных депутатов;"},{"key":"B","ro":"cu o majoritate de cel puțin trei cincimi din voturile tuturor deputaților;","ru":"большинством не менее трёх пятых от голосов всех депутатов;"},{"key":"C","ro":"cu o majoritate de cel puțin două treimi din voturile tuturor deputaților.","ru":"большинством не менее двух третей от голосов всех депутатов"}],"correct":"C"},{"id":11,"question":{"ro":"Parlamentul Republicii Moldova se întrunește:","ru":"Парламент Республики Молдова собирается:"},"options":[{"key":"A","ro":"oricând este nevoie, la solicitarea deputaților;","ru":"когда угодно по запросу депутатов;"},{"key":"B","ro":"într-o singură sesiune pe durata mandatului;","ru":"в одну сессию на протяжении срока полномочий;"},{"key":"C","ro":"în două sesiuni ordinare pe an;","ru":"в две обычные сессии в год;"},{"key":"D","ro":"oricând este nevoie, la solicitarea Președintelui Parlamentului","ru":"когда угодно по запросу Председателя Парламента."}],"correct":"C"},{"id":12,"question":{"ro":"Pământul, subsolul, apele, alte resurse naturale aflate pe teritoriul unității teritoriale autonome Găgăuzia sunt proprietatea:","ru":"Земля, недра, воды и другие природные ресурсы, расположенные на территории автономной территориальной единицы Гагаузия, являются собственностью:"},"options":[{"key":"A","ro":"locuitorilor din unitatea teritorială autonomă Găgăuzia;","ru":"жителей автономной территориальной единицы Гагаузия;"},{"key":"B","ro":"organelor administrației publice locale din unitatea teritorială autonomă Găgăuzia;","ru":"органов местного управления автономной территориальной единицы Гагаузия;"},{"key":"C","ro":"poporului Republicii Moldova.","ru":"народа Республики Молдова."}],"correct":"C"},{"id":13,"question":{"ro":"Care din autoritățile publice indicate mai jos nu dispune de dreptul la inițiativă legislativă:","ru":"Какая из указанных ниже органов государственной власти не обладает правом законодательной инициативы:"},"options":[{"key":"A","ro":"Președintele Republicii Moldova;","ru":"Президент Республики Молдова;"},{"key":"B","ro":"Consiliul Superior al Magistraturii;","ru":"Высший совет магистратуры;"},{"key":"C","ro":"Guvernul Republicii Moldova;","ru":"Правительство Республики Молдова;"},{"key":"D","ro":"Adunarea Populară a unității teritoriale autonome Găgăuzia.","ru":"Народное собрание автономной территориальной единицы Гагаузия."}],"correct":"B"},{"id":14,"question":{"ro":"Potrivit Constituției Republicii Moldova, legile ordinare se adoptă:","ru":"Согласно Конституции Республики Молдова, обычные законы принимаются:"},"options":[{"key":"A","ro":"cu votul majorității deputaților aleși;","ru":"голосованием большинства избранных депутатов;"},{"key":"B","ro":"cu votul a cel puțin două treimi din deputații aleși;","ru":"голосованием не менее двух третей избранных депутатов;"},{"key":"C","ro":"cu votul majorității deputaților prezenți la ședință.","ru":"голосованием большинства депутатов, присутствующих на заседании"}],"correct":"C"},{"id":15,"question":{"ro":"În exercitarea atribuțiilor sale, Guvernul Republicii Moldova se conduce de programul său de activitate, acceptat de către:","ru":"При осуществлении своих полномочий Правительство Республики Молдова руководствуется своей программой деятельности, принятой:"},"options":[{"key":"A","ro":"Comisia Electorală Centrală;","ru":"Центральной избирательной комиссией;"},{"key":"B","ro":"Fracțiunea parlamentară majoritară;","ru":"Парламентской фракцией большинства;"},{"key":"C","ro":"Președintele Republicii Moldova;","ru":"Президентом Республики Молдова;"},{"key":"D","ro":"Parlament.","ru":"Парламентом"}],"correct":"D"},{"id":16,"question":{"ro":"Structura, organizarea și funcționarea Parlamentului Republicii Moldova se stabilesc:","ru":"Структура, организация и функционирование Парламента Республики Молдова устанавливаются:"},"options":[{"key":"A","ro":"Prin Legea bugetului de stat;","ru":"Законом о государственном бюджете;"},{"key":"B","ro":"Prin regulament;","ru":"Регламентом;"},{"key":"C","ro":"Prin decretul Președintelui Republicii Moldova;","ru":"Указом Президента Республики Молдова;"},{"key":"D","ro":"Prin hotărârea Curții Constituționale.","ru":"Решением Конституционного суда."}],"correct":"B"},{"id":17,"question":{"ro":"Guvernul Republicii Moldova adoptă:","ru":"Правительство Республики Молдова принимает:"},"options":[{"key":"A","ro":"hotărâri și dispoziții;","ru":"постановления и распоряжения;"},{"key":"B","ro":"hotărâri, ordonanțe și dispoziții;","ru":"постановления, ордонансы и распоряжения;"},{"key":"C","ro":"legi, hotărâri și ordonanțe.","ru":"законы, постановления и ордонансы"}],"correct":"B"},{"id":18,"question":{"ro":"Legea organică care reglementează statutul special al unității teritoriale autonome Găgăuzia poate fi modificată:","ru":"Органический закон, регулирующий особый статус автономной территориальной единицы Гагаузия, может быть изменён:"},"options":[{"key":"A","ro":"cu votul majorității deputaților aleși în Parlament;","ru":"большинством голосов избранных депутатов Парламента;"},{"key":"B","ro":"cu votul a trei cincimi din numărul deputaților aleși în Parlament;","ru":"голосами трёх пятых от числа избранных депутатов Парламента;"},{"key":"C","ro":"cu votul a două treimi din numărul deputaților aleși în Parlament.","ru":"голосами двух третей от числа избранных депутатов Парламента."}],"correct":"B"},{"id":19,"question":{"ro":"Bugetul public național al Republicii Moldova este constituit din:","ru":"Национальный публичный бюджет Республики Молдова состоит из:"},"options":[{"key":"A","ro":"bugetul asigurărilor sociale de stat și bugetele raioanelor, orașelor și satelor.","ru":"бюджета государственного социального страхования и бюджетов районов, городов и сёл;"},{"key":"B","ro":"bugetul de stat, bugetul asigurărilor sociale de stat și bugetele raioanelor, orașelor și satelor.","ru":"государственного бюджета, бюджета государственного социального страхования и бюджетов районов, городов и сёл;"},{"key":"C","ro":"bugetul de stat și bugetele raioanelor, orașelor și satelor.","ru":"государственного бюджета и бюджетов районов, городов и сёл"}],"correct":"B"},{"id":20,"question":{"ro":"Curtea Constituțională a Republicii Moldova exercită la sesizare:","ru":"Конституционный суд Республики Молдова по обращению осуществляет:"},"options":[{"key":"A","ro":"controlul constituționalității legilor Parlamentului, a decretelor Președintelui Republicii Moldova, a ordonanțelor Guvernului;","ru":"контроль конституционности законов Парламента, указов Президента Республики Молдова и ордонансов Правительства;"},{"key":"B","ro":"controlul constituționalității legilor și hotărârilor Parlamentului, a decretelor Președintelui Republicii Moldova, a hotărârilor și ordonanțelor Guvernului, a tratatelor internaționale la care Republica Moldova este parte;","ru":"контроль конституционности законов и постановлений Парламента, указов Президента Республики Молдова, постановлений и ордонансов Правительства, международных договоров, стороной которых является Республика Молдова;"},{"key":"C","ro":"controlul constituționalității legilor, hotărârilor și moțiunilor Parlamentului, a decretelor și dispozițiilor Președintelui Republicii Moldova, a hotărârilor Guvernului, a tratatelor internaționale la care Republica Moldova este parte.","ru":"контроль конституционности законов, постановлений и вотумов Парламента, указов и распоряжений Президента Республики Молдова, постановлений Правительства и международных договоров, стороной которых является Республика Молдова."}],"correct":"B"},{"id":21,"question":{"ro":"Potrivit Constituției Republicii Moldova, legile organice se adoptă:","ru":"Согласно Конституции Республики Молдова, органические законы принимаются:"},"options":[{"key":"A","ro":"cu votul a cel puțin două treimi din deputații aleși, după cel puțin trei lecturi","ru":"голосами не менее двух третей избранных депутатов после как минимум трёх чтений;"},{"key":"B","ro":"cu votul majorității deputaților prezenți, după cel puțin două lecturi","ru":"большинством голосов депутатов, присутствующих на заседании, после как минимум двух чтений;"},{"key":"C","ro":"cu votul majorității deputaților aleși, după cel puțin două lecturi.","ru":"большинством голосов избранных депутатов после как минимум двух чтений."}],"correct":"C"},{"id":22,"question":{"ro":"Rezultatul alegerilor pentru funcția de Președinte al Republicii Moldova este validat de:","ru":"Результат выборов на должность Президента Республики Молдова утверждается:"},"options":[{"key":"A","ro":"Comisia Electorală Centrală;","ru":"Центральной избирательной комиссией;"},{"key":"B","ro":"Curtea Constituțională;","ru":"Конституционным судом;"},{"key":"C","ro":"Curtea Supremă de Justiție;","ru":"Высшей судебной палатой;"},{"key":"D","ro":"Parlament.","ru":"Парламентом."}],"correct":"B"},{"id":23,"question":{"ro":"Potrivit Constituției Republicii Moldova, în cazul demisiei Prim-ministrului:","ru":"Согласно Конституции Республики Молдова, в случае отставки Премьер-министра:"},"options":[{"key":"A","ro":"Demisionează întreg Guvernul;","ru":"уходит в отставку всё Правительство;"},{"key":"B","ro":"Miniștrii își exercită funcția în continuare;","ru":"министры продолжают исполнять свои обязанности;"},{"key":"C","ro":"Demisionează doar membrii Guvernului desemnați de Prim-ministru.","ru":"в отставку уходят только члены Правительства, назначенные Премьер-министром."}],"correct":"A"},{"id":24,"question":{"ro":"Conform Constituției Republicii Moldova, durata săptămânii de muncă este de cel mult:","ru":"Согласно Конституции Республики Молдова, продолжительность рабочей недели составляет не более:"},"options":[{"key":"A","ro":"40 de ore;","ru":"40 часов;"},{"key":"B","ro":"48 de ore;","ru":"48 часов;"},{"key":"C","ro":"36 de ore.","ru":"36 часов."}],"correct":"A"},{"id":25,"question":{"ro":"Cetățenii Republicii Moldova se bucură de protecția statului:","ru":"Граждане Республики Молдова пользуются защитой государства:"},"options":[{"key":"A","ro":"pe teritoriul Republicii Moldova;","ru":"на территории Республики Молдова;"},{"key":"B","ro":"pe teritoriul statelor membre ale Uniunii Europene;","ru":"на территории государств — членов Европейского союза;"},{"key":"C","ro":"atât în țară, cât și în străinătate;","ru":"как в стране, так и за границей;"},{"key":"D","ro":"pe teritoriul statelor cu care Republica Moldova are acorduri bilaterale.","ru":"на территории государств, с которыми Республика Молдова заключила двусторонние соглашения."}],"correct":"C"},{"id":26,"question":{"ro":"Potrivit Constituției Republicii Moldova, candidatul pentru funcția de Prim-ministru va cere Parlamentului:","ru":"Согласно Конституции Республики Молдова, кандидат на должность Премьер-министра просит у Парламента:"},"options":[{"key":"A","ro":"numirea Guvernului;","ru":"назначения Правительства;"},{"key":"B","ro":"aprobarea întregii liste a Guvernului;","ru":"утверждения полного состава Правительства;"},{"key":"C","ro":"votul de încredere al Parlamentului asupra programului de activitate și a întregii liste a Guvernului.","ru":"вотума доверия Парламента программе деятельности и полному составу Правительства."}],"correct":"C"},{"id":27,"question":{"ro":"Organele centrale de specialitate ale statului Republica Moldova sunt:","ru":"Центральными специализированными органами государства Республики Молдова являются:"},"options":[{"key":"A","ro":"ministerele;","ru":"министерства;"},{"key":"B","ro":"ministerele și agențiile;","ru":"министерства и агентства;"},{"key":"C","ro":"ministerele, agențiile și consiliile de administrare.","ru":"министерства, агентства и административные советы."}],"correct":"A"},{"id":28,"question":{"ro":"Potrivit Constituției Republicii Moldova, Găgăuzia este:","ru":"«Согласно Конституции Республики Молдова, Гагаузия является:"},"options":[{"key":"A","ro":"un raion cu un statut special;","ru":"районом с особым статусом;"},{"key":"B","ro":"o regiune cu un statut special;","ru":"регионом с особым статусом;"},{"key":"C","ro":"o unitate teritorială autonomă cu un statut special.","ru":"автономным территориальным образованием с особым статусом»"}],"correct":"C"},{"id":29,"question":{"ro":"În Republica Moldova, înființarea de instanțe judecătorești extraordinare:","ru":"В Республике Молдова создание чрезвычайных судебных инстанций:"},"options":[{"key":"A","ro":"este admisă în situații excepționale.","ru":"допускается в исключительных ситуациях;"},{"key":"B","ro":"este admisă în situația de război;","ru":"допускается в условиях войны;"},{"key":"C","ro":"este interzisă.","ru":"запрещено;"},{"key":"D","ro":"este admisă doar pentru examinarea cauzelor de corupție.","ru":"допускается только для рассмотрения дел о коррупции"}],"correct":"C"},{"id":30,"question":{"ro":"Procurorul General este demis din funcție de către:","ru":"Генеральный прокурор освобождается от должности:"},"options":[{"key":"A","ro":"Consiliul Superior al Procurorilor;","ru":"Высшим советом прокуроров;"},{"key":"B","ro":"Parlamentul Republicii Moldova;","ru":"Парламентом Республики Молдова;"},{"key":"C","ro":"Președintele Republicii Moldova.","ru":"Президентом Республики Молдова"}],"correct":"C"},{"id":31,"question":{"ro":"Președintele Curții de Conturi este numit:","ru":"Председатель Счётной палаты назначается:"},"options":[{"key":"A","ro":"de Parlament;","ru":"Парламентом;"},{"key":"B","ro":"de Președintele Republicii Moldova;","ru":"Президентом Республики Молдова;"},{"key":"C","ro":"de Guvern.","ru":"Правительством."}],"correct":"A"},{"id":32,"question":{"ro":"Nici o revizuire a Constituției Republicii Moldova nu poate fi făcută, dacă:","ru":"Никакой пересмотр Конституции Республики Молдова не может быть осуществлен, если:"},"options":[{"key":"A","ro":"are ca rezultat reforma organizării administrative a teritoriului;","ru":"он имеет своим результатом реформу административно-территориального устройства;"},{"key":"B","ro":"are ca rezultat suprimarea drepturilor și libertăților fundamentale ale cetățenilor sau a garanțiilor acestora;","ru":"он имеет своим результатом упразднение основных прав и свобод граждан или их гарантий;"},{"key":"C","ro":"are ca rezultat schimbarea formei de guvernământ;","ru":"он имеет своим результатом изменение формы правления;"},{"key":"D","ro":"are ca rezultat schimbarea regimului politic.","ru":"он имеет своим результатом изменение политического режима"}],"correct":"B"},{"id":33,"question":{"ro":"În Republica Moldova termenul arestării nu poate depăși:","ru":"В Республике Молдова общий срок ареста не может превышать:"},"options":[{"key":"A","ro":"72 ore;","ru":"72 часа (72 ore)"},{"key":"B","ro":"90 de zile;","ru":"90 дней (90 de zile)"},{"key":"C","ro":"12 luni;","ru":"12 месяцев (12 luni)"},{"key":"D","ro":"60 de zile.","ru":"60 дней (60 de zile)"}],"correct":"C"},{"id":34,"question":{"ro":"Deputații în Parlamentul Republicii Moldova intră în exercițiul mandatului:","ru":"Депутаты парламента Республики Молдова вступают в осуществление мандата:"},"options":[{"key":"A","ro":"din momentul stabilirii rezultatelor alegerilor de Comisia Electorală Centrală;","ru":"с момента установления результатов выборов Центральной избирательной комиссией;"},{"key":"B","ro":"sub condiția validării;","ru":"при условии валидации (подтверждения);"},{"key":"C","ro":"din momentul anunțării rezultatelor alegerilor parlamentare.","ru":"с момента объявления результатов парламентских выборов."}],"correct":"B"},{"id":35,"question":{"ro":"Parlamentul Republicii Moldova poate fi dizolvat:","ru":"Парламент Республики Молдова может быть распущен:"},"options":[{"key":"A","ro":"dacă a adoptat o moțiune de cenzură;","ru":"если он принял вотум недоверия (мотицию цензуры);"},{"key":"B","ro":"dacă a respins o inițiativă legislativă înaintată de Guvern;","ru":"если он отклонил законодательную инициативу, выдвинутую Правительством;"},{"key":"C","ro":"dacă nu a acceptat candidatul la funcția de Prim-Ministru înaintată de Președintele Republicii Moldova;","ru":"если он не принял кандидата на должность Премьер-министра, выдвинутого Президентом Республики Молдова;"},{"key":"D","ro":"dacă nu a acceptat votul de încredere pentru formarea Guvernului.","ru":"если он не принял вотум доверия для формирования Правительства."}],"correct":"D"},{"id":36,"question":{"ro":"Care din atribuțiile de mai jos nu ține de competența Președintelui Republicii Moldova:","ru":"Какое из нижеследующих полномочий не относится к компетенции Президента Республики Молдова:"},"options":[{"key":"A","ro":"grațierea individuală;","ru":"индивидуальное помилование;"},{"key":"B","ro":"conferirea decorațiilor și titlurilor de onoare;","ru":"присвоение орденов, медалей и почетных званий;"},{"key":"C","ro":"fixarea datei alegerilor locale generale;","ru":"назначение даты всеобщих местных выборов;"},{"key":"D","ro":"acordarea rangurilor diplomatice.","ru":"присвоение дипломатических рангов»"}],"correct":"C"},{"id":37,"question":{"ro":"Parlamentul nou ales al Republicii Moldova se întrunește:","ru":"Вновь избранный парламент Республики Молдова собирается:"},"options":[{"key":"A","ro":"la decizia Comisiei Electorale Centrale;","ru":"по решению Центральной избирательной комиссии;"},{"key":"B","ro":"la decizia Curții Constituționale;","ru":"по решению Конституционного суда;"},{"key":"C","ro":"la convocarea Președintelui Republicii Moldova.","ru":"по созыву Президента Республики Молдова."}],"correct":"C"},{"id":38,"question":{"ro":"Parlamentul Republicii Moldova se întrunește în sesiuni extraordinare:","ru":"Парламент Республики Молдова собирается на внеочередные сессии:"},"options":[{"key":"A","ro":"la cererea Președintelui Republicii Moldova, a Președintelui Parlamentului, a unei treimi din deputați sau la cererea Adunării Naționale;","ru":"по требованию Президента Республики Молдова, Председателя Парламента, одной трети депутатов или по требованию Национального собрания;"},{"key":"B","ro":"la cererea Președintelui Republicii Moldova, a Președintelui Parlamentului sau a unei treimi din deputați;","ru":"по требованию Президента Республики Молдова, Председателя Парламента или одной трети депутатов;"},{"key":"C","ro":"la cererea Adunării naționale, a Adunării Populare a UTA Găgăuzia, a Președintelui Republicii Moldova, a Președintelui Parlamentului, a unei treimi din deputați.","ru":"по требованию Национального собрания, Народного собрания АТО Гагаузия, Президента Республики Молдова, Председателя Парламента, одной трети депутатов."}],"correct":"B"},{"id":39,"question":{"ro":"Acreditarea și rechemarea reprezentanților diplomatici ai Republicii Moldova sunt efectuate de către:","ru":"Аккредитация и отзыв дипломатических представителей Республики Молдова осуществляются:"},"options":[{"key":"A","ro":"Președintele Republicii Moldova la propunerea Guvernului;","ru":"Президентом Республики Молдова по предложению Правительства;"},{"key":"B","ro":"Prim-ministru la propunerea Ministerului de Externe și Integrare Europeană;","ru":"Премьер-министром по предложению Министерства иностранных дел и европейской интеграции;"},{"key":"C","ro":"Președintele Parlamentului la propunerea Guvernului.","ru":"Председателем Парламента по предложению Правительства."}],"correct":"A"},{"id":40,"question":{"ro":"În Republica Moldova dreptul persoanei de a avea acces la orice informație de interes public:","ru":"В Республике Молдова право лица на доступ к любой информации общественного интереса:"},"options":[{"key":"A","ro":"poate fi realizat numai în baza hotărârii instanței de judecată;","ru":"может быть реализовано только на основании решения судебной инстанции;"},{"key":"B","ro":"nu poate fi îngrădit;","ru":"не может быть ограничено;"},{"key":"C","ro":"poate fi realizat doar la acordul autorității ce deține informația.","ru":"может быть реализовано только с согласия органа, владеющего информацией."}],"correct":"B"},{"id":41,"question":{"ro":"Deputații în Parlamentul Republicii Moldova nu pot fi persecutați sau trași la răspundere juridică pentru:","ru":"Депутаты Парламента Республики Молдова не могут преследоваться или привлекаться к юридической ответственности за:"},"options":[{"key":"A","ro":"contravenții;","ru":"правонарушения (проступки);"},{"key":"B","ro":"încălcarea disciplinei de partid;","ru":"нарушение партийной дисциплины;"},{"key":"C","ro":"opiniile exprimate în exercitarea mandatului.","ru":"мнения, выраженные при осуществлении мандата."}],"correct":"C"},{"id":42,"question":{"ro":"În Republica Moldova grevele pot fi declanșate:","ru":"В Республике Молдова забастовки могут быть объявлены:"},"options":[{"key":"A","ro":"în scopul apărării intereselor cu caracter economic și social ale cetățenilor;","ru":"в целях защиты интересов экономического и социального характера граждан;"},{"key":"B","ro":"în scopul majorării salariilor și perfecționării condițiilor de muncă;","ru":"в целях повышения заработной платы и улучшения условий труда;"},{"key":"C","ro":"în scopul apărării intereselor profesionale cu caracter economic și social ale salariaților.","ru":"в целях защиты профессиональных интересов экономического и социального характера работников."}],"correct":"C"},{"id":43,"question":{"ro":"Judecătorii instanțelor judecătorești din Republica Moldova sunt numiți în funcție de către:","ru":"Судьи судебных инстанций Республики Молдова назначаются на должность:"},"options":[{"key":"A","ro":"Președintele Republicii Moldova;","ru":"Президентом Республики Молдова;"},{"key":"B","ro":"Consiliul Superior al Magistraturii;","ru":"Высшим советом магистратуры;"},{"key":"C","ro":"Parlamentul Republicii Moldova;","ru":"Парламентом Республики Молдова;"},{"key":"D","ro":"Președintele Parlamentului.","ru":"Председателем Парламента."}],"correct":"A"},{"id":44,"question":{"ro":"Mandatul Parlamentului Republicii Moldova poate fi prelungit:","ru":"Мандат Парламента Республики Молдова может быть продлен:"},"options":[{"key":"A","ro":"prin lege constituțională, în caz de război sau de catastrofă;","ru":"конституционным законом в случае войны или катастрофы;"},{"key":"B","ro":"prin lege organică, în caz de război sau de catastrofă;","ru":"органическим законом в случае войны или катастрофы;"},{"key":"C","ro":"prin hotărârea Parlamentului adoptată cu votul a 2/3 din numărul deputaților aleși.","ru":"постановлением Парламента, принятым голосами 2/3 от числа избранных депутатов."}],"correct":"B"},{"id":45,"question":{"ro":"În Republica Moldova referendumului sunt supuse:","ru":"В Республике Молдова на референдум выносятся:"},"options":[{"key":"A","ro":"problemele privind relațiile cu Uniunea Europeană;","ru":"вопросы, касающиеся отношений с Европейским союзом;"},{"key":"B","ro":"cele mai importante probleme ale societății și ale statului;","ru":"наиболее важные проблемы общества и государства;"},{"key":"C","ro":"problemele de ordin național;","ru":"проблемы национального характера;"},{"key":"D","ro":"problemele de politică externă.","ru":"проблемы внешней политики."}],"correct":"B"},{"id":46,"question":{"ro":"În Republica Moldova, calitatea de deputat este incompatibilă:","ru":"В Республике Молдова статус депутата несовместим:"},"options":[{"key":"A","ro":"cu exercitarea oricărei alte funcții retribuite, cu excepția activității didactice și științifice;","ru":"с занятием любой другой оплачиваемой должности, за исключением преподавательской и научной деятельности;"},{"key":"B","ro":"cu exercitarea oricărei alte funcții retribuite, cu excepția activității în organele administrației publice locale;","ru":"с занятием любой другой оплачиваемой должности, за исключением деятельности в органах местного публичного управления;"},{"key":"C","ro":"cu exercitarea oricărei alte funcții retribuite, cu excepția activității în organele judecătorești.","ru":"с занятием любой другой оплачиваемой должности, за исключением деятельности в судебных органах."}],"correct":"A"},{"id":47,"question":{"ro":"Președintele Parlamentului Republicii Moldova se alege:","ru":"Председатель Парламента Республики Молдова избирается:"},"options":[{"key":"A","ro":"cu votul a cel puțin două treimi din voturile tuturor deputaților;","ru":"голосами не менее двух третей от общего числа депутатов;"},{"key":"B","ro":"cu majoritatea voturilor deputaților aleși;","ru":"большинством голосов избранных депутатов;"},{"key":"C","ro":"cu majoritatea voturilor deputaților prezenți la ședință.","ru":"большинством голосов депутатов, присутствующих на заседании."}],"correct":"B"},{"id":48,"question":{"ro":"Potrivit Constituției Republicii Moldova, legile ordinare reglementează:","ru":"Согласно Конституции Республики Молдова, ординарные законы регулируют:"},"options":[{"key":"A","ro":"orice domenii pentru care Parlamentul consideră necesară adoptarea de legi ordinare;","ru":"любые сферы, для которых Парламент считает необходимым принятие ординарных законов;"},{"key":"B","ro":"orice domeniu al relațiilor sociale, cu excepția celor rezervate legilor constituționale și legilor organice;","ru":"любую сферу общественных отношений, за исключением тех, которые закреплены за конституционными и органическими законами;"},{"key":"C","ro":"organizarea administrației locale, a teritoriului, precum și regimul general privind autonomia locală;","ru":"организацию местного публичного управления, территории, а также общий режим местного самоуправления;"},{"key":"D","ro":"raporturile de muncă, sindicatele și protecția socială.","ru":"трудовые отношения, профсоюзы и социальную защиту."}],"correct":"B"},{"id":49,"question":{"ro":"Este declarat ales în funcția de Președinte al Republicii Moldova candidatul care a întrunit:","ru":"Избранным на должность Президента Республики Молдова объявляется кандидат, который набрал:"},"options":[{"key":"A","ro":"cel puțin jumătate din voturile alegătorilor înscriși în listele de alegători;","ru":"по меньшей мере половину голосов избирателей, внесенных в списки избирателей;"},{"key":"B","ro":"cel puțin o treime din voturile alegătorilor ce au participat la alegeri;","ru":"по меньшей мере одну треть голосов избирателей, принявших участие в выборах;"},{"key":"C","ro":"cel puțin jumătate din voturile alegătorilor ce au participat la alegeri;","ru":"не менее половины голосов избирателей, принявших участие в выборах;"},{"key":"D","ro":"cel puțin o treime din voturile alegătorilor înscriși în listele de alegători.","ru":"по меньшей мере одну треть голосов избирателей, внесенных в списки избирателей"}],"correct":"C"},{"id":50,"question":{"ro":"Propunerea de suspendare din funcție a Președintelui Republicii Moldova poate fi inițiată:","ru":"Предложение о временном отстранении от должности (субсидиарно — импичменте/приостановке полномочий) Президента Республики Молдова может быть инициировано:"},"options":[{"key":"A","ro":"de cel puțin 100 de mii de cetățeni cu drept de vot;","ru":"не менее 100 тысяч граждан с правом голоса;"},{"key":"B","ro":"de Curtea Constituțională;","ru":"Конституционным судом;"},{"key":"C","ro":"de cel puțin o treime din deputați;","ru":"не менее одной трети депутатов;"},{"key":"D","ro":"de Curtea Supremă de Justiție.","ru":"Высшей судебной палатой"}],"correct":"C"},{"id":51,"question":{"ro":"Guvernul Republicii Moldova este alcătuit din:","ru":"Из кого состоит Правительство Республики Молдова?"},"options":[{"key":"A","ro":"Prim-ministru, viceprim-miniștri, miniștri, secretari de stat și alți membri stabiliți prin lege organică;","ru":"Премьер-министр, вице-премьер-министры, министры, государственные секретари и другие члены, установленные органическим законом;"},{"key":"B","ro":"Prim-ministru, miniștri, secretari de stat și alți membri stabiliți prin lege organică;","ru":"Премьер-министр, министры, государственные секретари и другие члены, установленные органическим законом;"},{"key":"C","ro":"Prim-ministru, prim-viceprim-ministru, viceprim-miniștri, miniștri și alți membri stabiliți prin lege organică.","ru":"Премьер-министр, первый вице-премьер-министр, вице-премьер-министры, министры и другие члены, установленные органическим законом"}],"correct":"C"},{"id":52,"question":{"ro":"Programul de activitate și lista Guvernului se dezbat în:","ru":"Программа деятельности и список Правительства обсуждаются на:"},"options":[{"key":"A","ro":"ședința comună a fracțiunilor parlamentare;","ru":"совместном заседании парламентских фракций;"},{"key":"B","ro":"ședința Biroului permanent al Parlamentului;","ru":"заседании Постоянного бюро Парламента;"},{"key":"C","ro":"ședința Parlamentului.","ru":"заседании Парламента."}],"correct":"C"},{"id":53,"question":{"ro":"Forțele armate ale Republicii Moldova sunt subordonate:","ru":"Вооруженные силы Республики Молдова подчиняются:"},"options":[{"key":"A","ro":"Președintelui Republicii Moldova;","ru":"Президенту Республики Молдова;"},{"key":"B","ro":"Comandantului Suprem al Forțelor armate;","ru":"Главнокомандующему Вооруженными силами;"},{"key":"C","ro":"Ministrului apărării;","ru":"Министру обороны;"},{"key":"D","ro":"Exclusiv poporului.","ru":"Исключительно народу"}],"correct":"D"},{"id":54,"question":{"ro":"Controlul asupra respectării legislației Republicii Moldova în unitatea teritorială autonomă Găgăuzia se exercită:","ru":"Контроль за соблюдением законодательства Республики Молдова в территориальном автономном образовании Гагаузия осуществляется:"},"options":[{"key":"A","ro":"de Parlament;","ru":"парламентом;"},{"key":"B","ro":"de Guvern;","ru":"правительством;"},{"key":"C","ro":"de Procuratura generală;","ru":"генеральной прокуратурой;"},{"key":"D","ro":"de Curtea Constituțională.","ru":"конституционным судом"}],"correct":"B"},{"id":55,"question":{"ro":"În Republica Moldova justiția se înfăptuiește prin:","ru":"В Республике Молдова правосудие осуществляется посредством:"},"options":[{"key":"A","ro":"Curtea Supremă de Justiție, prin curțile de apel și prin judecătorii;","ru":"Высшей судебной палаты, апелляционных палат и судов;"},{"key":"B","ro":"Curtea Supremă de Justiție, prin curțile de apel, tribunale și prin judecătorii;","ru":"Высшей судебной палаты, апелляционных палат, трибуналов и судов;"},{"key":"C","ro":"Curtea Supremă de Justiție, prin curțile de apel, Curtea anticorupție și prin judecătorii;","ru":"Высшей судебной палаты, апелляционных палат, Антикоррупционного суда и судов."}],"correct":"A"},{"id":56,"question":{"ro":"Parlamentul Republicii Moldova este în drept să adopte o lege cu privire la modificarea Constituției:","ru":"Парламент Республики Молдова имеет право принять закон о внесении изменений в Конституцию:"},"options":[{"key":"A","ro":"după cel mult 6 luni de la data prezentării inițiativei corespunzătoare;","ru":"не позднее чем через 6 месяцев со дня представления соответствующей инициативы;"},{"key":"B","ro":"după cel puțin 12 luni de la data prezentării inițiativei corespunzătoare;","ru":"по истечении не менее 12 месяцев со дня представления соответствующей инициативы;"},{"key":"C","ro":"după cel puțin 6 luni de la data prezentării inițiativei corespunzătoare.","ru":"по истечении не менее 6 месяцев со дня представления соответствующей инициативы"}],"correct":"C"},{"id":57,"question":{"ro":"În Republica Moldova reținerea nu poate depăși:","ru":"В Республике Молдова задержание не может превышать:"},"options":[{"key":"A","ro":"48 ore;","ru":"48 часов;"},{"key":"B","ro":"24 ore;","ru":"24 часов;"},{"key":"C","ro":"72 ore;","ru":"72 часов;"},{"key":"D","ro":"3 ore.","ru":"3 часов."}],"correct":"C"},{"id":58,"question":{"ro":"Potrivit Constituției Republicii Moldova, dispozițiile privind drepturile și libertățile omului se interpretează și se aplică:","ru":"Согласно Конституции Республики Молдова, положения о правах и свободах человека толкуются и применяются:"},"options":[{"key":"A","ro":"în concordanță cu Constituția Uniunii Europene, prevederile tratatelor internaționale la care Republica Moldova este parte;","ru":"в соответствии с Конституцией Европейского Союза, положениями международных договоров, стороной которых является Республика Молдова;"},{"key":"B","ro":"în concordanță cu Pactul cu privire la Drepturile Civile și Politice, Pactul cu privire la Drepturile Sociale, Econimice și Culturale și celelalte tratate la care Republica Moldova este parte;","ru":"в соответствии с Пактом о гражданских и политических правах, Пактом об экономических, социальных и культурных правах и другими договорами, стороной которых является Республика Молдова;"},{"key":"C","ro":"în concordanță cu Declarația Universală a Drepturilor Omului, cu pactele și cu celelalte tratate la care Republica Moldova este parte.","ru":"в соответствии со Всеобщей декларацией прав человека, пактами и другими договорами, стороной которых является Республика Молдова"}],"correct":"C"},{"id":59,"question":{"ro":"Potrivit Constituției Republicii Moldova, legile constituționale sunt:","ru":"Согласно Конституции Республики Молдова, конституционными законами являются:"},"options":[{"key":"A","ro":"cele de revizuire a Constituției;","ru":"законы о пересмотре Конституции;"},{"key":"B","ro":"cele prin care se stabilește starea de asediu sau de război;","ru":"законы, устанавливающие осадное или военное положение;"},{"key":"C","ro":"cele prin care se ratifică tratatele internaționale la care Republica Moldova este parte;","ru":"законы, ратифицирующие международные договоры, стороной которых является Республика Молдова;"},{"key":"D","ro":"cele prin care este reglementată organizarea și funcționarea Curții Constituționale, a Consiliului Superior al Magistraturii, a instanțelor judecătorești, a contenciosului administrativ.","ru":"законы, регулирующие организацию и деятельность Конституционного суда, Высшего совета магистратуры, судебных инстанций, административного контента."}],"correct":"A"},{"id":60,"question":{"ro":"Calitatea de Președinte al Republicii Moldova este incompatibilă cu exercitarea:","ru":"Должность Президента Республики Молдова несовместима с осуществлением:"},"options":[{"key":"A","ro":"activității didactice sau științifice;","ru":"преподавательской или научной деятельности;"},{"key":"B","ro":"oricărei alte funcții retribuite;","ru":"любой другой оплачиваемой должности;"},{"key":"C","ro":"activității în calitate de membru al unor organizații interguvernamentale.","ru":"деятельности в качестве члена межправительственных организаций."}],"correct":"B"},{"id":61,"question":{"ro":"Potrivit Constituției, pedeapsa cu moartea în Republica Moldova:","ru":"Согласно Конституции, смертная казнь в Республике Молдова:"},"options":[{"key":"A","ro":"este abolită;","ru":"отменена;"},{"key":"B","ro":"poate fi aplicată doar pentru infracțiuni de înaltă trădare;","ru":"может применяться только за преступления против государственной измены;"},{"key":"C","ro":"poate fi aplicată doar pentru infracțiuni de război;","ru":"может применяться только за военные преступления;"},{"key":"D","ro":"poate fi aplicată doar la decizia Curții Supreme de Justiție.","ru":"может применяться только по решению Верховного суда справедливости."}],"correct":"A"},{"id":62,"question":{"ro":"În cursul unui an, Parlamentul Republicii Moldova poate fi dizolvat:","ru":"В течение одного года Парламент Республики Молдова может быть распущен:"},"options":[{"key":"A","ro":"de câte ori decid deputații;","ru":"сколько раз решат депутаты;"},{"key":"B","ro":"de 3 ori;","ru":"3 раза;"},{"key":"C","ro":"o singură dată;","ru":"один раз;"},{"key":"D","ro":"de 2 ori.","ru":"2 раза."}],"correct":"C"},{"id":63,"question":{"ro":"Legile adoptate de Parlamentul Republicii Moldova sunt promulgate de către:","ru":"Законы, принятые Парламентом Республики Молдова, провозглашаются (промульгируются):"},"options":[{"key":"A","ro":"Președintele Parlamentului;","ru":"Председателем Парламента;"},{"key":"B","ro":"Președintele Republicii Moldova;","ru":"Президентом Республики Молдова;"},{"key":"C","ro":"Guvernul Republicii Moldova;","ru":"Правительством Республики Молдова;"},{"key":"D","ro":"Prim-ministru.","ru":"Премьер-министром."}],"correct":"B"},{"id":64,"question":{"ro":"Parlamentul poate hotărî punerea sub acuzare a Președintelui Republicii Moldova:","ru":"Парламент может принять решение об обвинении (привлечении к ответственности) Президента Республики Молдова:"},"options":[{"key":"A","ro":"în cazul în care refuză promulgarea unei legi adoptate de Parlament;","ru":"в случае отказа провозгласить (подписать) закон, принятый Парламентом;"},{"key":"B","ro":"în cazul în care săvârșește o infracțiune;","ru":"в случае совершения им преступления;"},{"key":"C","ro":"în cazul în care emite decretul de dizolvare a Parlamentului în ultimele 6 luni ale mandatului.","ru":"в случае издания указа о роспуске Парламента в последние 6 месяцев его мандата."}],"correct":"B"},{"id":65,"question":{"ro":"Procurorul General este numit în funcție:","ru":"Генеральный прокурор назначается на должность:"},"options":[{"key":"A","ro":"pentru un mandat de 5 ani;","ru":"на 5-летний срок;"},{"key":"B","ro":"pentru un mandat de 7 ani;","ru":"на 7-летний срок;"},{"key":"C","ro":"pentru un mandat de 6 ani.","ru":"на 6-летний срок»."}],"correct":"B"},{"id":66,"question":{"ro":"Președintele Republicii Moldova revocă și numește pe unii membri ai Guvernului la propunerea:","ru":"Президент Республики Молдова отзывает и назначает отдельных членов Правительства по предложению:"},"options":[{"key":"A","ro":"Președintelui Parlamentului;","ru":"Председателя Парламента;"},{"key":"B","ro":"Prim-ministrului,","ru":"Премьер-министра;"},{"key":"C","ro":"Curții Constituționale.","ru":"Конституционного суда."}],"correct":"B"},{"id":67,"question":{"ro":"Parlamentul Republicii Moldova își poate exprima neîncrederea în Guvern la propunerea:","ru":"Парламент Республики Молдова может выразить недоверие Правительству по предложению:"},"options":[{"key":"A","ro":"a cel puțin o pătrime din deputați;","ru":"не менее одной четверти депутатов;"},{"key":"B","ro":"majorității parlamentare;","ru":"парламентского большинства;"},{"key":"C","ro":"Președintelui Republicii Moldova.","ru":"Президента Республики Молдова."}],"correct":"A"},{"id":68,"question":{"ro":"În baza votului de încredere acordat de Parlament, Guvernul Republicii Moldova este numit de:","ru":"На основании голоса доверия, предоставленного Парламентом, Правительство Республики Молдова назначается:"},"options":[{"key":"A","ro":"Președintele Parlamentului;","ru":"Председателем Парламента;"},{"key":"B","ro":"Președintele republicii;","ru":"Президентом республики;"},{"key":"C","ro":"Președintele Curții Constituționale.","ru":"Председателем Конституционного суда."}],"correct":"B"},{"id":69,"question":{"ro":"În cazul în care are obiecții asupra unei legi transmise spre promulgare, Președintele Republicii Moldova este în drept:","ru":"В случае если у Президента Республики Молдова имеются возражения относительно закона, представленного для промульгации, он вправе:"},"options":[{"key":"A","ro":"să o trimită, în termen de cel mult cinci zile lucrătoare, spre reexaminare, Guvernului;","ru":"направить его в срок не более пяти рабочих дней на повторное рассмотрение Правительству;"},{"key":"B","ro":"să o trimită, în termen de cel mult două săptămâni, spre reexaminare, Parlamentului;","ru":"направить его в срок не более двух недель на повторное рассмотрение Парламенту;"},{"key":"C","ro":"să o trimită, în termen de cel mult două săptămâni, spre reexaminare, autorului legii.","ru":"направить его в срок не более двух недель на повторное рассмотрение автору закона."}],"correct":"B"},{"id":70,"question":{"ro":"Funcția de membru al Guvernului Republicii Moldova este incompatibilă cu:","ru":"Функция члена Правительства Республики Молдова несовместима с:"},"options":[{"key":"A","ro":"exercitarea activității comerciale;","ru":"осуществлением коммерческой деятельности;"},{"key":"B","ro":"exercitarea activității politice;","ru":"осуществлением политической деятельности;"},{"key":"C","ro":"exercitarea oricărei alte funcții retribuite.","ru":"осуществлением любой другой оплачиваемой функции"}],"correct":"C"},{"id":71,"question":{"ro":"În Republica Moldova proprietatea publică aparține:","ru":"В Республике Молдова государственная собственность принадлежит:"},"options":[{"key":"A","ro":"statului și asociațiilor comerciale;","ru":"государству и коммерческим ассоциациям;"},{"key":"B","ro":"statului sau unităților administrativ-teritoriale;","ru":"государству или административно-территориальным единицам;"},{"key":"C","ro":"statului sau consiliilor locale;","ru":"государству или местным советам;"},{"key":"D","ro":"statului sau instituțiilor și autorităților publice.","ru":"государству или учреждениям и публичным органам власти"}],"correct":"B"},{"id":72,"question":{"ro":"Ordonanțele adoptate de Guvernul Republicii Moldova intră în vigoare:","ru":"Ордонансы, принятые Правительством Республики Молдова, вступают в силу:"},"options":[{"key":"A","ro":"după promulgare, la data publicării;","ru":"после промульгации, в дату опубликования;"},{"key":"B","ro":"la data publicării, fără a fi promulgate;","ru":"в дату опубликования, без промульгации;"},{"key":"C","ro":"după promulgare, la data indicată în text;","ru":"после промульгации, в дату, указанную в тексте;"},{"key":"D","ro":"din momentul adoptări.","ru":"с момента принятия."}],"correct":"B"},{"id":73,"question":{"ro":"În Republica Moldova, dreptul exclusiv la emisia monetară aparține:","ru":"В Республике Молдова исключительное право на денежную эмиссию (выпуск денег) принадлежит:"},"options":[{"key":"A","ro":"Guvernului Republicii Moldova;","ru":"Правительству Республики Молдова;"},{"key":"B","ro":"Băncii Naționale a Republicii Moldova;","ru":"Национальному банку Молдовы;"},{"key":"C","ro":"Ministerului Finanțelor;","ru":"Министерству финансов;"},{"key":"D","ro":"Comisiei Naționale a Pieței Financiare din Republica Moldova.","ru":"Национальной комиссии финансового рынка Республики Молдова"}],"correct":"B"},{"id":74,"question":{"ro":"Guvernul Republicii Moldova își exercită mandatul:","ru":"Правительство Республики Молдова осуществляет свой мандат:"},"options":[{"key":"A","ro":"până la demisia Prim-ministrului;","ru":"до отставки Премьер-министра;"},{"key":"B","ro":"până la data validării alegerilor pentru un nou Parlament;","ru":"до даты утверждения выборов нового Парламента;"},{"key":"C","ro":"până la acordarea de către parlament a votului de încredere noului Guvern.","ru":"до предоставления Парламентом голоса доверия новому Правительству."}],"correct":"B"},{"id":75,"question":{"ro":"Judecătorii Curții Constituționale se numesc:","ru":"Судьи Конституционного суда назначаются:"},"options":[{"key":"A","ro":"pentru un mandat de 6 ani;","ru":"на мандат сроком на 6 лет;"},{"key":"B","ro":"pentru un mandat de 7 ani;","ru":"на мандат сроком на 7 лет;"},{"key":"C","ro":"pe viață.","ru":"пожизненно."}],"correct":"A"},{"id":76,"question":{"ro":"Autoritățile administrației publice prin care se exercită autonomia locală în sate și în orașe, sunt:","ru":"Органами публичной администрации, через которые осуществляется местное самоуправление в селах и городах, являются:"},"options":[{"key":"A","ro":"consilierii și primarii aleși;","ru":"избранные советники и избранные примары;"},{"key":"B","ro":"consiliile locale alese și primarii aleși;","ru":"избранные местные советы и избранные примары;"},{"key":"C","ro":"consiliile locale alese, primarii și oficiile teritoriale ale Cancelariei de Stat.","ru":"избранные местные советы, примары и территориальные отделения Государственной канцелярии."}],"correct":"B"},{"id":77,"question":{"ro":"Parlamentul Republicii Moldova adoptă:","ru":"Парламент Республики Молдова принимает:"},"options":[{"key":"A","ro":"legi speciale, legi constituționale, legi marțiale și legi organice;","ru":"специальные законы, конституционные законы, военные законы и органические законы;"},{"key":"B","ro":"legi constituționale, legi organice și legi ordinare;","ru":"конституционные законы, органические законы и обычные (ординарные) законы;"},{"key":"C","ro":"legi constituționale, legi speciale, legi formale și legi ordinare.","ru":"конституционные законы, специальные законы, формальные законы и обычные законы."}],"correct":"B"},{"id":78,"question":{"ro":"Consiliul Superior al Procurorilor este constituit:","ru":"Высший совет прокуроров состоит:"},"options":[{"key":"A","ro":"din procurori aleși din cadrul procuraturilor de toate nivelurile și din reprezentanți ai altor autorități, instituții publice sau ai societății civile;","ru":"из прокуроров, избранных из прокуратур всех уровней, и представителей других органов власти, публичных учреждений или гражданского общества;"},{"key":"B","ro":"din procurori desemnați de Parlament și din reprezentanți ai instituțiilor publice sau ai societății civile;","ru":"из прокуроров, назначенных Парламентом, и представителей публичных учреждений или гражданского общества;"},{"key":"C","ro":"din procurori aleși de Institutul National al Justiției și din reprezentanți ai societății civile.","ru":"из прокуроров, избранных Национальным институтом юстиции, и представителей гражданского общества"}],"correct":"A"},{"id":79,"question":{"ro":"Hotărârile Curții Constituționale a Republicii Moldova:","ru":"Решения Конституционного суда Республики Молдова:"},"options":[{"key":"A","ro":"nu pot fi atacate;","ru":"не могут быть обжалованы;"},{"key":"B","ro":"pot fi atacate la Curtea Supremă de Justiție;","ru":"могут быть обжалованы в Верховном суде правосудия;"},{"key":"C","ro":"pot fi atacate la Curtea Europeană a Drepturilor Omului.","ru":"могут быть обжалованы в Европейском суде по правам человека."}],"correct":"A"},{"id":80,"question":{"ro":"În Republica Moldova, protecția mediului înconjurător constituie o obligație:","ru":"В Республике Молдова защита окружающей среды является обязанностью:"},"options":[{"key":"A","ro":"a fiecărei persoane;","ru":"каждого лица;"},{"key":"B","ro":"a fiecărui cetățean;","ru":"каждого гражданина;"},{"key":"C","ro":"a fiecărui cetățean și persoane juridice.","ru":"каждого гражданина и юридического лица"}],"correct":"B"},{"id":81,"question":{"ro":"Potrivit Constituției Republicii Moldova, averea dobândită licit:","ru":"Согласно Конституции Республики Молдова, имущество, приобретенное законным путем:"},"options":[{"key":"A","ro":"nu poate fi confiscată;","ru":"не может быть конфисковано;"},{"key":"B","ro":"poate fi confiscată potrivit legii;","ru":"может быть конфисковано согласно закону;"},{"key":"C","ro":"poate fi confiscată dacă este folosită irațional.","ru":"может быть конфисковано, если используется нерационально."}],"correct":"A"},{"id":82,"question":{"ro":"Potrivit Constituției Republicii Moldova, perchezițiile și cercetările la fața locului pot fi ordonate și efectuate numai:","ru":"Согласно Конституции Республики Молдова, обыски и осмотр места происшествия могут быть назначены и проведены только:"},"options":[{"key":"A","ro":"în cazul săvârșirii unor infracțiuni;","ru":"в случае совершения преступлений;"},{"key":"B","ro":"în condițiile legii;","ru":"в порядке и на условиях, предусмотренных законом;"},{"key":"C","ro":"în baza unei hotărâri judecătorești.","ru":"на основании судебного решения."}],"correct":"B"},{"id":83,"question":{"ro":"Modul de funcționare a limbilor pe teritoriul Republicii Moldova se stabilește prin:","ru":"Порядок функционирования языков на территории Республики Молдова устанавливается:"},"options":[{"key":"A","ro":"Constituția Republicii Moldova;","ru":"Конституцией Республики Молдова;"},{"key":"B","ro":"Hotărârea Parlamentului Republicii Moldova;","ru":"Постановлением Парламента Республики Молдова;"},{"key":"C","ro":"Lege organică.","ru":"органическим законом."}],"correct":"C"},{"id":84,"question":{"ro":"Care sunt factorii de bază ai economiei stabiliți în Constituția Republicii Moldova?","ru":"Каковы основные факторы экономики, установленные в Конституции Республики Молдова?"},"options":[{"key":"A","ro":"economia de piață, proprietatea privată și concurența loială;","ru":"рыночная экономика, частная собственность и добросовестная конкуренция;"},{"key":"B","ro":"statul inovațional și libera inițiativă economică;","ru":"инновационное государство и свободная экономическая инициатива;"},{"key":"C","ro":"piața, libera inițiativă economică, concurența loială.","ru":"рынок, свободная экономическая инициатива, добросовестная конкуренция."}],"correct":"C"},{"id":85,"question":{"ro":"Constituția Republicii Moldova declară drept obiectiv strategic:","ru":"Конституция Республики Молдова объявляет в качестве стратегической цели:"},"options":[{"key":"A","ro":"integrarea în Uniunea Europeană și spațiul euroatlantic;","ru":"интеграцию в Европейский союз и евроатлантическое пространство;"},{"key":"B","ro":"garantarea drepturilor omului;","ru":"гарантирование прав человека;"},{"key":"C","ro":"integrarea în Uniunea Europeană;","ru":"интеграцию в Европейский союз;"},{"key":"D","ro":"statul de drept.","ru":"правовое государство."}],"correct":"C"},{"id":86,"question":{"ro":"Potrivit Constituției Republicii Moldova, îndatorirea primordială a statului constă în:","ru":"Согласно Конституции Республики Молдова, первостепенная обязанность государства состоит в:"},"options":[{"key":"A","ro":"respectarea Cartei Organizației Națiunilor Unite și tratatelor la care este parte;","ru":"соблюдении Устава Организации Объединенных Наций и договоров, участником которых оно является;"},{"key":"B","ro":"neutralitatea sa permanentă;","ru":"его постоянном нейтралитете;"},{"key":"C","ro":"respectarea și ocrotirea persoanei.","ru":"уважении и защите личности."}],"correct":"C"},{"id":87,"question":{"ro":"Conform Constituției Republicii Moldova, cetățenii străini și apatrizii pot fi extrădați:","ru":"Согласно Конституции Республики Молдова, иностранные граждане и лица без гражданства могут быть экстрадированы (выданы другому государству):"},"options":[{"key":"A","ro":"în cazul nerespectării termenului de ședere;","ru":"в случае несоблюдения срока пребывания;"},{"key":"B","ro":"în baza unei convenții internaționale sau în temeiul hotărârii instanței de judecată;","ru":"на основании международной конвенции или на основании решения судебной инстанции;"},{"key":"C","ro":"în cazul săvârșirii unor infracțiuni sau în temeiul hotărârii instanței de judecată.","ru":"в случае совершения преступлений или на основании решения судебной инстанции"}],"correct":"B"},{"id":88,"question":{"ro":"În Republica Moldova, funcțiile publice ai căror titulari nu pot face parte din partide se stabilesc:","ru":"В Республике Молдова перечень государственных должностей, которые не могут занимать члены политических партий, устанавливается:"},"options":[{"key":"A","ro":"prin hotărârea Curții Constituționale;","ru":"решением Конституционного суда;"},{"key":"B","ro":"prin lege organică;","ru":"органическим законом;"},{"key":"C","ro":"prin hotărârea Guvernului;","ru":"постановлением Правительства;"},{"key":"D","ro":"prin lege constituțională.","ru":"конституционным законом."}],"correct":"B"},{"id":89,"question":{"ro":"Organizarea și desfășurarea referendumului se reglementează:","ru":"Организация и проведение референдума регулируются:"},"options":[{"key":"A","ro":"prin Constituția Republicii Moldova;","ru":"Конституцией Республики Молдова;"},{"key":"B","ro":"prin lege ordinară;","ru":"обычным законом;"},{"key":"C","ro":"prin lege organică.","ru":"органическим законом."}],"correct":"C"},{"id":90,"question":{"ro":"În Republica Moldova, pluralismul politic este incompatibil:","ru":"В Республике Молдова политический плюрализм несовместим:"},"options":[{"key":"A","ro":"cu regimul politic totalitar;","ru":"с тоталитарным политическим режимом;"},{"key":"B","ro":"cu regimul politic comunist;","ru":"с коммунистическим политическим режимом;"},{"key":"C","ro":"cu dictatura și cu totalitarismul.","ru":"с диктатурой и тоталитаризмом"}],"correct":"C"},{"id":91,"question":{"ro":"Democrația în Republica Moldova se exercită în condițiile:","ru":"Демократия в Республике Молдова осуществляется в условиях:"},"options":[{"key":"A","ro":"pluripartismului de opinii;","ru":"многопартийности мнений;"},{"key":"B","ro":"principiului majorității;","ru":"принципа большинства;"},{"key":"C","ro":"disciplinii sociale;","ru":"социальной дисциплины;"},{"key":"D","ro":"pluralismului politic.","ru":"политического плюрализма."}],"correct":"D"},{"id":92,"question":{"ro":"Potrivit Constituției, Republica Moldova este patria comună:","ru":"Согласно Конституции, Республика Молдова является общей родиной:"},"options":[{"key":"A","ro":"a tuturor cetățenilor săi;","ru":"всех своих граждан;"},{"key":"B","ro":"a cetățenilor Republicii Moldova și a cetățenilor străini;","ru":"граждан Республики Молдова и иностранных граждан;"},{"key":"C","ro":"a persoanelor care au dobândit cetățenia Republicii Moldova prin naștere.","ru":"лиц, которые приобрели гражданство Республики Молдова по рождению"}],"correct":"A"},{"id":93,"question":{"ro":"Culorile Drapelului de Stat al Republicii Moldova sunt dispuse:","ru":"Цвета Государственного флага Республики Молдова расположены:"},"options":[{"key":"A","ro":"vertical, în ordinea următoare, începând de la lance: albastru, galben, roșu;","ru":"вертикально, в следующем порядке, начиная от древка: синий, желтый, красный;"},{"key":"B","ro":"vertical, în ordinea următoare, începând de la lance: roșu, galben, albastru;","ru":"вертикально, в следующем порядке, начиная от древка: красный, желтый, синий;"},{"key":"C","ro":"vertical, în ordinea următoare, începând de la lance: galben, albastru, roșu.","ru":"вертикально, в следующем порядке, начиная от древка: желтый, синий, красный."}],"correct":"A"},{"id":94,"question":{"ro":"Potrivit Constituției Republicii Moldova, statul facilitează studierea:","ru":"Согласно Конституции Республики Молдова, государство содействует изучению:"},"options":[{"key":"A","ro":"limbii române pentru alolingvi;","ru":"румынского языка иноязычными (лицами, говорящими на других языках);"},{"key":"B","ro":"limbilor de circulație internațională;","ru":"языков международного общения;"},{"key":"C","ro":"limbilor minorităților naționale.","ru":"языков национальных меньшинств."}],"correct":"B"},{"id":95,"question":{"ro":"Cetățenii Republicii Moldova beneficiază de drepturile și de libertățile consacrate prin:","ru":"Граждане Республики Молдова пользуются правами и свободами, установленными:"},"options":[{"key":"A","ro":"Constituție și prin alte legi;","ru":"Конституцией и другими законами;"},{"key":"B","ro":"Constituție, prin legi și hotărâri ale Guvernului;","ru":"Конституцией, законами и постановлениями Правительства;"},{"key":"C","ro":"Declarația Europeană a Drepturilor Omului;","ru":"Европейской декларацией прав человека;"},{"key":"D","ro":"Declarația Universală a Drepturilor Omului și prin Constituție.","ru":"Всеобщей декларацией прав человека и Конституцией."}],"correct":"A"},{"id":96,"question":{"ro":"Potrivit Constituției Republicii Moldova, eliberarea celui reținut sau arestat este obligatorie dacă:","ru":"Согласно Конституции Республики Молдова, освобождение задержанного или арестованного является обязательным, если:"},"options":[{"key":"A","ro":"a fost introdusă cauțiunea;","ru":"был внесён залог;"},{"key":"B","ro":"avocatul a contestat decizia instanței;","ru":"адвокат обжаловал решение суда;"},{"key":"C","ro":"motivele reținerii sau arestării au dispărut;","ru":"основания задержания или ареста исчезли;"},{"key":"D","ro":"dacă acesta și-a recunoscut vina.","ru":"если он признал свою вину"}],"correct":"C"},{"id":97,"question":{"ro":"Oricărui cetățean al Republicii Moldova îi este asigurat dreptul de a-și stabili domiciliul sau reședința:","ru":"Каждому гражданину Республики Молдова обеспечивается право на выбор места жительства или места пребывания:"},"options":[{"key":"A","ro":"în orice localitate din tara și din străinătate;","ru":"в любом населенном пункте страны и за рубежом;"},{"key":"B","ro":"în orice localitate din țară;","ru":"в любом населенном пункте страны;"},{"key":"C","ro":"în orice localitate din țară și din statele cu care Republica Moldova are încheiate acorduri.","ru":"в любом населенном пункте страны и государств, с которыми Республика Молдова заключила соглашения"}],"correct":"B"},{"id":98,"question":{"ro":"În Republica Moldova perchezițiile în timpul nopții sunt interzise, în afară de:","ru":"В Республике Молдова обыски в ночное время запрещены, за исключением:"},"options":[{"key":"A","ro":"cazul în care autoritățile sunt informate că în încăpere sunt minori;","ru":"случая, когда органы власти проинформированы о том, что в помещении находятся несовершеннолетние;"},{"key":"B","ro":"cazul unui delict flagrant;","ru":"случая задержания на месте преступления/случая совершения преступления с поличным (по горячим следам / flagrante delicto);"},{"key":"C","ro":"cazul în care nu există o hotărâre judecătorească.","ru":"случая, когда отсутствует решение суда"}],"correct":"B"},{"id":99,"question":{"ro":"În Republica Moldova studierea limbii române se asigură:","ru":"В Республике Молдова изучение румынского языка обеспечивается:"},"options":[{"key":"A","ro":"în instituțiile de învățământ de toate gradele;","ru":"в учебных заведениях всех ступеней;"},{"key":"B","ro":"în instituțiile de învățământ general;","ru":"в учреждениях общего образования;"},{"key":"C","ro":"în învățământul liceal.","ru":"в лицейском образовании."}],"correct":"A"},{"id":100,"question":{"ro":"Potrivit Constituției, baza puterii de stat în Republica Moldova o constituie:","ru":"Согласно Конституции, основу государственной власти в Республике Молдова составляет:"},"options":[{"key":"A","ro":"voința poporului;","ru":"воля народа;"},{"key":"B","ro":"voința cetățenilor;","ru":"воля граждан;"},{"key":"C","ro":"voința alegătorilor.","ru":"воля избирателей"}],"correct":"A"},{"id":101,"question":{"ro":"În Republica Moldova, accesul la o funcție publică se asigură:","ru":"В Республике Молдова доступ к государственной должности обеспечивается:"},"options":[{"key":"A","ro":"oricărei persoane care dispune de calificarea necesară;","ru":"любому лицу, имеющему необходимую квалификацию;"},{"key":"B","ro":"oricărei persoane care dispune de experiență în domeniul public;","ru":"любому лицу, имеющему опыт работы в государственной сфере;"},{"key":"C","ro":"oricărui cetățean;","ru":"любому гражданину;"},{"key":"D","ro":"oricărui cetățean care cunoaște limba română.","ru":"любому гражданину, владеющему румынским языком"}],"correct":"C"},{"id":102,"question":{"ro":"Orice salariat are dreptul de a întemeia și de a se afilia la sindicate pentru:","ru":"Каждый работник имеет право создавать и вступать в профессиональные союзы для:"},"options":[{"key":"A","ro":"apărarea intereselor sale;","ru":"защиты своих интересов;"},{"key":"B","ro":"negocieri în materie de muncă;","ru":"ведения переговоров в сфере труда;"},{"key":"C","ro":"stabilirea regimului de muncă, instituirea unui salariu minim pe economie, repaosul săptămânal, concediul de odihnă plătit, prestarea muncii în condiții grele, precum și pentru alte scopuri specifice.","ru":"установления режима труда, введения минимальной заработной платы по экономике, еженедельного отдыха, оплачиваемого ежегодного отпуска, работы в тяжёлых условиях, а также для других специфических целей"}],"correct":"A"},{"id":103,"question":{"ro":"În Republica Moldova, o persoană poate fi supusă unui tratament medical forțat:","ru":"В Республике Молдова лицо может быть подвергнуто принудительному медицинскому лечению:"},"options":[{"key":"A","ro":"în cazul în care persoana nu dispune de capacitate juridică;","ru":"в случае, если лицо не обладает правоспособностью;"},{"key":"B","ro":"doar în cazurile prevăzute de lege;","ru":"только в предусмотренных законом случаях;"},{"key":"C","ro":"doar în cazul unei epidemii.","ru":"только в случае эпидемии."}],"correct":"B"},{"id":104,"question":{"ro":"Potrivit Constituției Republicii Moldova, pentru prejudiciile cauzate prin erorile săvârșite în procesele penale de către organele de anchetă și instanțele judecătorești poartă răspundere:","ru":"Согласно Конституции Республики Молдова, за ущерб, причинённый в результате ошибок, совершённых в уголовном процессе органами следствия и судебными инстанциями, несёт ответственность:"},"options":[{"key":"A","ro":"statul;","ru":"государство;"},{"key":"B","ro":"persoanele care au cauzat prejudiciile respective;","ru":"лица, причинившие соответствующий ущерб;"},{"key":"C","ro":"ofițerii de urmărire penală, procurorii și judecătorii care au cauzat prejudiciile respective.","ru":"сотрудники уголовного преследования, прокуроры и судьи, причинившие соответствующий ущерб."}],"correct":"A"},{"id":105,"question":{"ro":"În Republica Moldova, apărarea Patriei este:","ru":"В Республике Молдова защита Отечества является:"},"options":[{"key":"A","ro":"un drept și o datorie sfântă a fiecărui cetățean;","ru":"священным правом и долгом каждого гражданина;"},{"key":"B","ro":"un drept și o datorie sfântă a membrilor Forțelor Armate;","ru":"священным правом и долгом членов Вооруженных сил;"},{"key":"C","ro":"un drept și o datorie sfântă a fiecărei persoane cu domiciliu legal pe teritoriul Republicii Moldova.","ru":"священным правом и долгом каждого лица, имеющего законное место жительства на территории Республики Молдова."}],"correct":"A"},{"id":106,"question":{"ro":"Potrivit Constituției Republicii Moldova, în exercitarea mandatului, deputații:","ru":"Согласно Конституции Республики Молдова, при осуществлении мандата депутаты:"},"options":[{"key":"A","ro":"reprezintă interesele alegătorilor;","ru":"представляют интересы избирателей;"},{"key":"B","ro":"sunt în serviciul poporului;","ru":"находятся на службе народа;"},{"key":"C","ro":"sunt în serviciul statului;","ru":"находятся на службе государства;"},{"key":"D","ro":"sunt în serviciul cetățenilor.","ru":"находятся на службе граждан."}],"correct":"B"},{"id":107,"question":{"ro":"În Republica Moldova, orice deputat nu poate fi persecutat sau tras la răspundere juridică:","ru":"В Республике Молдова любой депутат не может быть преследуем или привлечён к юридической ответственности:"},"options":[{"key":"A","ro":"pentru voturile sau pentru opiniile exprimate în exercitarea mandatului;","ru":"за голоса или за мнения, выраженные при осуществлении мандата;"},{"key":"B","ro":"pentru participarea la acțiunile de protest;","ru":"за участие в акциях протеста;"},{"key":"C","ro":"pentru boicotarea ședințelor Parlamentului.","ru":"за бойкотирование заседаний Парламента"}],"correct":"A"},{"id":108,"question":{"ro":"Comandantul suprem al Forțelor Armate din Republica Moldova este:","ru":"Верховным главнокомандующим Вооруженными силами Республики Молдова является:"},"options":[{"key":"A","ro":"Ministrul apărării;","ru":"министр обороны;"},{"key":"B","ro":"Șeful Marelui Stat Major;","ru":"начальник Генерального штаба;"},{"key":"C","ro":"Președintele Republicii Moldova.","ru":"Президент Республики Молдова"}],"correct":"C"},{"id":109,"question":{"ro":"Prim-ministrul Republicii Moldova emite dispoziții pentru:","ru":"Премьер-министр Республики Молдова издаёт распоряжения для:"},"options":[{"key":"A","ro":"organizarea activității interne a Guvernului;","ru":"организации внутренней деятельности Правительства;"},{"key":"B","ro":"angajarea și eliberarea din funcție a miniștrilor;","ru":"назначения и освобождения министров с должности;"},{"key":"C","ro":"convocarea ședințelor Guvernului;","ru":"созыва заседаний Правительства;"},{"key":"D","ro":"pentru declararea stării de urgență.","ru":"объявления чрезвычайного положения."}],"correct":"A"},{"id":110,"question":{"ro":"Consiliul Superior al Magistraturii este:","ru":"Высший совет магистратуры является:"},"options":[{"key":"A","ro":"autoritatea judecătorească supremă;","ru":"высшим судебным органом;"},{"key":"B","ro":"organul de autoadministrare a sistemului judecătoresc;","ru":"органом самоуправления судебной системы;"},{"key":"C","ro":"garantul independenței autorității judecătorești;","ru":"гарантом независимости судебной власти;"},{"key":"D","ro":"garantul inviolabilității judecătorilor.","ru":"гарантом неприкосновенности судей."}],"correct":"C"},{"id":111,"question":{"ro":"În Republica Moldova Avocatul Poporului este numit:","ru":"В Республике Молдова Народный адвокат назначается:"},"options":[{"key":"A","ro":"de Președintele Republicii Moldova, în baza unei proceduri transparente de selecție;","ru":"Президентом Республики Молдова на основе прозрачной процедуры отбора;"},{"key":"B","ro":"de Parlament, în baza unei proceduri transparente de selecție;","ru":"Парламентом на основе прозрачной процедуры отбора;"},{"key":"C","ro":"de Curtea Supremă de Justiție, în rezultatul unui concurs;","ru":"Верховным судом правосудия по результатам конкурса;"},{"key":"D","ro":"de Consiliul Superior al Magistraturii, la propunerea Ministrului Justiției.","ru":"Высшим советом магистратуры по предложению министра юстиции"}],"correct":"B"}];
